/**
 * chart-meta.js
 *
 * Editorial metadata for the /data/ section. Each key matches a filename
 * (without .md) from the data source — the same keys as chart-configs.js.
 *
 * Charts listed here get their own page at /data/<slug>/, generated by
 * generate-data.js. The table content mirrors the source markdown exactly.
 *
 * The pages show only what the source file carries — its table and notes. No
 * interpretive prose or year spans are generated. The fields below are neutral
 * organizational metadata, not commentary on the data:
 *
 *   slug     — URL segment for the standalone page
 *   group    — company / topic grouping on the index page ("万科A", "宏观经济"…)
 *   metric   — short metric name used as the card title (group is the eyebrow)
 *   source   — data source line
 *   unit     — primary unit, when a single one applies
 *   preview  — index-card sparkline spec, rendered at build time from real data:
 *              type: 'line' | 'bar' | 'stackbar'
 *              color / colors: hex from the chart's own palette
 *              series(entry) → chronological values
 *                ('stackbar' returns [bottom, top] pairs)
 */
module.exports = {
  '万科A 合同负债': {
    slug: 'vanke-contract-liabilities',
    group: '万科A',
    metric: '合同负债',
    source: '万科A 年度报告',
    unit: '亿元',
    preview: {
      type: 'bar',
      color: '#0D95D0',
      series: entry => entry.rows.slice().reverse().map(r => r[1]),
    },
  },
  '万科A 有息负债及结构': {
    slug: 'vanke-interest-bearing-debt',
    group: '万科A',
    metric: '有息负债及期限结构',
    source: '万科A 年度报告',
    unit: '亿元',
    preview: {
      type: 'stackbar',
      colors: ['#EFB743', '#D44627'],
      series: entry => entry.rows.map(r => [r[3], r[5]]),
    },
  },
  '万科A 存货情况': {
    slug: 'vanke-inventory',
    group: '万科A',
    metric: '存货及构成',
    source: '万科A 年度报告',
    unit: '亿元',
    preview: {
      // Two bars (2024, 2025), each stacked by the four components (in 亿元)
      type: 'stackbar',
      colors: ['#EFB743', '#D44627', '#774FA0', '#7DC462'],
      series: entry => {
        const comp = entry.rows.slice(1);
        const toYi = v => v / 10000;
        return [
          comp.map(r => toYi(r[3])), // 2024 年末
          comp.map(r => toYi(r[1])), // 2025 年末
        ];
      },
    },
  },
  '万科A 房地产开发及相关资产经营业务毛利率': {
    slug: 'vanke-development-gross-margin',
    group: '万科A',
    metric: '房地产开发业务毛利率',
    source: '万科A 年度报告',
    unit: '%',
    preview: {
      type: 'line',
      color: '#D44627',
      series: entry => entry.rows.slice().reverse().map(r => r[1]),
    },
  },
  '中国居民个人住房贷款余额': {
    slug: 'china-personal-housing-loans',
    group: '宏观经济',
    metric: '中国居民个人住房贷款余额',
    source: '中国人民银行公开数据整理',
    unit: '万亿元',
    preview: {
      type: 'bar',
      color: '#774FA0',
      series: entry => entry.rows.slice().reverse().map(r => r[1]),
    },
  },
  '万物云住宅物业及物业设施管理项目数与饱和收入': {
    slug: 'onewo-managed-projects-income',
    group: '万物云',
    metric: '管理项目数与饱和收入',
    source: '万物云年度报告',
    preview: {
      // 在管项目饱和收入, per segment: [2024, 2025] pairs
      type: 'bar',
      colors: ['#EFB743', '#D44627', '#EFB743', '#D44627'],
      series: entry => {
        const pick = (seg, year) => {
          const row = entry.rows.find(r =>
            r[0] === seg && Number(r[1]) === year && r[2] === '在管项目饱和收入');
          return row ? row[3] : null;
        };
        return [
          pick('住宅物业服务', 2024), pick('住宅物业服务', 2025),
          pick('物业及设施管理服务', 2024), pick('物业及设施管理服务', 2025),
        ];
      },
    },
  },
};
